System.register("chunks:///_virtual/companion.json",[],(function(e){return{execute:function(){e("default",{tips:["Прыжок — смах вверх. Короткий смах, короткий прыжок.","На чайке ты в безопасности. Ветер толкает только в воздухе.","Вода не спешит, пока ты высоко. Завис — и она догонит.","Пушка ест один порох. Без заряда прыгай ногами.","Порох падает с бомб чайки-солдата. Прыгни по бомбе.","Обычная чайка монет не носит. Монеты у странных.","Яйцо не открывается само. Оно ждёт в сундуке.","Шкаф: скины и чайки. Закрытая чайка — просто тень.","Чайка открывается, когда за неё хватаешься.","Верстак помнит высоту. Таблица — неделя, всё время и чат.","Рекорд — черта в небе. Дотянись до неё.","Высоко дует вбок. Сел на чайку — и тебя не снесёт.","Падать можно. В воду — нельзя надолго.","Сундук хранит монеты, порох и трофеи.","Слоты пока молчат. Копи монеты заранее."],jokes:["Я бы и сама взлетела. Но кто-то должен смотреть снизу.","Море сегодня голодное. Не корми его пиратом.","Если чайка смотрит странно — она и есть странная.","Порох пахнет приключением. И немного серой.","Рекорд — это просто вчерашний страх, только выше.","Я считаю волны. Они считают тебя.","Не махай крыльями. У тебя их нет, и это нормально.","Сундук не кусается. В отличие от воды.","Ветер не злой. Ему просто скучно наверху.","Один прыжок ничего не решает. Десять — уже характер.","Я видела, как ты целился. Море тоже видело.","Чайка не лифт. Но сегодня пусть будет лифтом.","Если страшно — сядь. На чайку, не на дно.","Трофеи не летают. Зато ты летаешь за них.","Я молчу в полёте. Снизу советы слышнее."],stories:["Однажды пират допрыгал до тучи и не нашёл там клада. Нашёл ветер. Вернулся богаче, но мокрый.","Старая чайка носила монету в клюве три дня. На четвёртый отдала её тому, кто не отпустил когти.","Пушку отлили из якоря. Якорь обиделся и теперь лежит в сундуке, если повезёт.","На этом острове был капитан, который боялся воды. Он прыгал, пока вода не устала первой.","Шкаф когда-то был клеткой. Птицы вышли, а тени остались ждать свои имена.","Я сидела здесь, когда остров ещё был ниже. Море поднялось. Я осталась на месте.","Один пират копил порох и ни разу не выстрелил. Море забрало его тихо, без салюта.","Говорят, на самой вершине нет чаек. Я не проверяла. Мне и тут хорошо.","Первый рекорд нацарапали на мачте. Мачту унесло. Рекорд остался в небе.","Ночью чайки светят чужими глазами. Днём притворяются обычными. Не верь дню."],birds:{basic:"Обычная чайка — опора. Монет на ней нет, зато есть карты повыше.",crazy:"Бешеная дёргается. Не держись за неё слишком долго.",solder:"Солдат роняет бомбу. Прыжок по бомбе даёт порох.",zombie:"Зомби отпускает когти. Прыгай сразу, не жди.",ghost:"Призрак замедляет, если пролететь сквозь него.",freeze:"Морозная держит на месте. Коротко, но обидно.",rik:"Рик открывает окно вбок. Высоту сам не дарит.",thief:"Вор тащит монету этого забега. Не подставляйся.",scientist:"Учёный заражает стаю. Соседи тоже становятся зомби.",evil_wizard:"Звездочёт гасит день. В темноте прыгай на слух.",pirate:"Пиратская чайка берёт налог с монет, когда с неё спрыгиваешь.",storm:"Штормовая бьёт молнией по соседкам. Рядом тесно.",midas:"Золотая почти всегда с монетой. Редкая и щедрая.",joker:"Джокер приходит за картами. Собирай их с обычных чаек."},events:{record:"Новый рекорд. Черта в небе теперь твоя.",water:"Вода догнала. Не зависай на одной высоте.",fall:"Сорвался. Когти держат, только пока держишься ты.",mark:"Высота {n}. Дальше чайки злее, а ветер ощутимее.",artifact:"Первый трофей: {name}. Он лежит в сундуке.",powder:"Пороха нет. Прыгай сам или добудь заряд у солдата.",slots:"Пять монет — и барабан крутится. Три вида в бестиарии дают одно бесплатное вращение в день."}})}}}));

